// 一次性探针（只读）: 验「发现6」—— 全局读失败时不许把世界书条目当"关闭"删掉。
//
// ── 这个 bug 是什么 ──
//  `getVariables({global})` 抛错 → `getSettings` 返回 store 里那份（可能是全默认值）
//  → `更新.世界书写入 = '关闭'`（默认值）→ `maybeInjectNpcStates` 判出"关闭"
//  → `syncNpcStatesWorldbook` 把两本世界书里的彼方条目**删掉**，全程无提示。
//
// ── 判据（需求方 #362 发现6 原文）──
//  构造 `getVariables` 抛错 → 断言**没有删除任何世界书条目**。
//
// ── 为什么要真跑 ──
//  "读失败 → 不删" 读代码能看出来，但**它会不会被别的路径绕过**只有跑起来才知道。
//  所以这里跑**三条**真实调用路径：maybeInjectNpcStates / 建变更环境.同步世界书 / update 那条。
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { buildTest } from '../build.mjs';
import path from 'node:path';

const 此处 = path.dirname(fileURLToPath(import.meta.url));
const 入口 = path.join(此处, '_probe-found6.ts');
const 产物 = path.join(此处, '_probe-found6.mjs');

const 源码 = [
  "import { createPinia, setActivePinia } from 'pinia';",
  "setActivePinia(createPinia());",
  "import { maybeInjectNpcStates } from '../../src/彼方_NPC幕后生命状态系统/worldbook-inject';",
  "import { invalidateReadCache, 设置读取可信, getSettings } from '../../src/彼方_NPC幕后生命状态系统/settings';",
  "import { BIFANG_WORLDBOOK_ENTRY_NAME } from '../../src/彼方_NPC幕后生命状态系统/彼方条目';",
  "",
  "let 通过 = 0, 失败 = 0;",
  "const 断言 = (名, 实际, 期望) => {",
  "  const ok = JSON.stringify(实际) === JSON.stringify(期望);",
  "  if (ok) 通过++; else 失败++;",
  "  console.log('  ' + (ok ? '✅' : '★ ') + '  ' + 名 + (ok ? '' : '  实际=' + JSON.stringify(实际) + ' 期望=' + JSON.stringify(期望)));",
  "};",
  "",
  "const 原I = console.info, 原W = console.warn, 原E = console.error, 原T = console.table;",
  "console.info = () => {}; console.warn = () => {}; console.error = () => {}; console.table = () => {};",
  "",
  "/** 造一本假世界书，里面预置一条彼方条目（有 extra.bifang） */",
  "function 造世界书() {",
  "  const 书 = { 条目: [{ name: BIFANG_WORLDBOOK_ENTRY_NAME, content: '[彼方 · 幕后NPC状态]\\n甲 | 位置: 家', enabled: true, extra: { bifang: true } }] };",
  "  let 删了几次 = 0;",
  "  const host = {",
  "    worldbook: {",
  "      boundNames: () => ({ primary: '主世界书', additional: [] }),",
  "      boundNamesOf: () => ({ primary: null, additional: [] }),",
  "      groupMemberNames: () => [],",
  "      chatName: () => null,",
  "      getOrCreateChat: async () => '聊天世界书',",
  "      entries: async () => 书.条目.map(e => ({ ...e })),",
  "      update: async (n, fn) => { 书.条目 = fn(书.条目); },",
  "      create: async (n, 新增) => { 书.条目.push(...新增); },",
  "      remove: async (n, 谓词) => { 删了几次++; 书.条目 = 书.条目.filter(e => !谓词(e)); },",
  "    },",
  "    toast: { warn: () => {}, success: () => {}, info: () => {} },",
  "  };",
  "  return { host, 书, 取删次数: () => 删了几次 };",
  "}",
  "",
  "/** 让 getVariables({global}) 抛错 —— 这就是那个 bug 的触发条件 */",
  "function 让全局读失败(host) {",
  "  host.vars = {",
  "    get: (arg) => { if (arg?.type === 'global') throw new Error('模拟：全局变量读不到'); return {}; },",
  "    update: () => {},",
  "    scriptId: () => 'fake',",
  "  };",
  "}",
  "",
  "/** 正常能读的 vars */",
  "function 让全局可读(host, 设置) {",
  "  host.vars = {",
  "    get: (arg) => arg?.type === 'global' ? { 彼方_settings: 设置 } : {},",
  "    update: () => {},",
  "    scriptId: () => 'fake',",
  "  };",
  "}",
  "",
  "try {",
  "  console.log('=== ① 读失败时，设置读取可信() 必须为 false ===');",
  "  {",
  "    const { host } = 造世界书();",
  "    让全局读失败(host);",
  "    invalidateReadCache();",
  "    const s = getSettings(host);",
  "    console.log('    读失败后 getSettings 返回的 世界书写入 = ' + JSON.stringify(s.更新.世界书写入));",
  "    断言('读失败 → 设置读取可信() 为 false', 设置读取可信(), false);",
  "    断言('读失败 → 世界书写入 是默认值「关闭」（这就是那个陷阱）', s.更新.世界书写入, '关闭');",
  "  }",
  "",
  "  console.log('');",
  "  console.log('=== ② 读失败时 maybeInjectNpcStates 不许删条目 ===');",
  "  {",
  "    const { host, 书, 取删次数 } = 造世界书();",
  "    让全局读失败(host);",
  "    invalidateReadCache();",
  "    getSettings(host); // 先把「读失败」这个状态建立起来",
  "    maybeInjectNpcStates(host);",
  "    await new Promise(r => setTimeout(r, 50)); // 等 fire-and-forget 那条链跑完",
  "    console.log('    条目数: ' + 书.条目.length + '  remove 被调: ' + 取删次数() + ' 次');",
  "    断言('★ 彼方条目没被删', 书.条目.some(e => e.extra?.bifang === true), true);",
  "    断言('★ remove 一次都没被调', 取删次数(), 0);",
  "  }",
  "",
  "  console.log('');",
  "  console.log('=== ③ 自证：读成功且用户真的关掉时，必须照常删 ===');",
  "  {",
  "    const { host, 书, 取删次数 } = 造世界书();",
  "    让全局可读(host, { 启用幕后: true, 更新: { 世界书写入: '关闭' } });",
  "    invalidateReadCache();",
  "    getSettings(host);",
  "    断言('读成功 → 设置读取可信() 为 true', 设置读取可信(), true);",
  "    maybeInjectNpcStates(host);",
  "    await new Promise(r => setTimeout(r, 50));",
  "    console.log('    条目数: ' + 书.条目.length + '  remove 被调: ' + 取删次数() + ' 次');",
  "    断言('[自证] 真关闭时条目被删了', 书.条目.length, 0);",
  "    断言('[自证] 真关闭时 remove 被调过', 取删次数() > 0, true);",
  "  }",
  "",
  "  console.log('');",
  "  console.log('=== ④ 自证：读成功时，合法的删除必须照常发生（防「干脆都别删」）===');",
  "  // ── 为什么用「NPC 为空」这个场景 ──",
  "  //  它是**读成功时合法的删除**：条目是当前状态的镜像，没状态就该删（可逆，数据一恢复就重建）。",
  "  //  拿它当对照，能证明闸门只挡「读失败」这一种，没有顺手把正常删除也挡掉。",
  "  //  ⚠ 我第一版用「写入开着 + 有 NPC」当对照，结果 false —— 那是探针没布置 NPC 数据，",
  "  //     走的是 NPC 为空那条删条目路径。**红的是探针，不是代码。**",
  "  {",
  "    const { host, 书, 取删次数 } = 造世界书();",
  "    让全局可读(host, { 启用幕后: true, 更新: { 世界书写入: '角色卡主世界书' } });",
  "    invalidateReadCache();",
  "    getSettings(host);",
  "    maybeInjectNpcStates(host); // 没有 NPC 数据 → 合法地删掉条目",
  "    await new Promise(r => setTimeout(r, 80));",
  "    console.log('    条目数: ' + 书.条目.length + '  remove 被调: ' + 取删次数() + ' 次');",
  "    断言('[自证] 读成功时合法删除照常发生（闸门没把正常路径也挡掉）', 取删次数() > 0, true);",
  "  }",
  "}",
  "finally {",
  "  console.info = 原I; console.warn = 原W; console.error = 原E; console.table = 原T;",
  "}",
  "",
  "console.log('');",
  "console.log('结果: ' + 通过 + ' 通过, ' + 失败 + ' 失败');",
  "process.exit(失败 > 0 ? 1 : 0);",
].join('\n');

writeFileSync(入口, 源码);

await buildTest(入口, 产物);
await import(new URL(`file:///${产物.replace(/\\/g, '/')}`).href);
